The following SQL statements have been executed: What will the output be of the last select statement?
create or replace sequence seq_01 start = 1 increment = 2;
create or replace table sequence_test_table (i integer);

select seq_01.nextval;
select seq_01.nextval;

insert into sequence_test_table (i) values (seq_01.nextval);
select seq_01.nextval;
